#include "fluxtabletprofiles.h"
#include <QSettings>
#include <QtMath>

QVector<FluxTabletProfile> FluxTabletProfiles::profiles(){QSettings s("Flux","Flux Studio");QVector<FluxTabletProfile> out;const int n=s.beginReadArray("tabletProfiles");for(int i=0;i<n;++i){s.setArrayIndex(i);FluxTabletProfile p;p.deviceId=s.value("deviceId").toString();p.name=s.value("name",p.deviceId).toString();p.driver=s.value("driver").toString();p.primaryAction=s.value("primary","Brush").toString();p.barrelAction=s.value("barrel","Pan").toString();p.eraserAction=s.value("eraser","Eraser").toString();p.windowsInk=s.value("windowsInk",true).toBool();p.enabled=s.value("enabled",true).toBool();out.push_back(p);}s.endArray();return out;}
void FluxTabletProfiles::setProfile(const FluxTabletProfile&profile){QSettings s("Flux","Flux Studio");auto list=profiles();bool found=false;for(auto&p:list)if(p.deviceId==profile.deviceId){p=profile;found=true;}if(!found)list.push_back(profile);s.beginWriteArray("tabletProfiles");for(int i=0;i<list.size();++i){s.setArrayIndex(i);const auto&p=list[i];s.setValue("deviceId",p.deviceId);s.setValue("name",p.name);s.setValue("driver",p.driver);s.setValue("primary",p.primaryAction);s.setValue("barrel",p.barrelAction);s.setValue("eraser",p.eraserAction);s.setValue("windowsInk",p.windowsInk);s.setValue("enabled",p.enabled);}s.endArray();}
FluxTabletProfile FluxTabletProfiles::profileFor(const QString&deviceId){for(const auto&p:profiles())if(p.deviceId==deviceId)return p;FluxTabletProfile p;p.deviceId=deviceId;p.name=deviceId;return p;}
qreal FluxTabletProfiles::mapPressure(const FluxTabletProfile&p,qreal pressure){const auto&c=p.pressureCurve;if(c.isEmpty())return qBound(0.0,pressure,1.0);const qreal x=qBound(0.0,pressure,1.0);for(int i=1;i<c.size();++i)if(x<=c[i].input){const auto&a=c[i-1];const auto&b=c[i];const qreal t=(x-a.input)/qMax(0.0001,b.input-a.input);return qBound(0.0,a.output+(b.output-a.output)*t,1.0);}return qBound(0.0,c.last().output,1.0);}
